//! Cycles: the sub-collections within a set (the five Gods of Amonkhet, its Cartouches, the
//! Nine of the Lord of the Rings…). Those of the MTG Wiki live in `config/cycles.json`
//! (generated by `.cache/build-cycles.js`, never edited by hand), ours in
//! `config/cycles.custom.json`, which may also replace or hide one of the wiki's. A cycle is
//! made of slots, one a card, each slot the collector numbers of its printings in the set,
//! the least premium first: the best copy owned of any of them fills the slot.

use crate::booster::ConfigError;
use serde::Deserialize;
use std::collections::{BTreeMap, HashMap, HashSet};

/// The wiki's cycles (`config/cycles.json`).
#[derive(Debug, Clone, Deserialize)]
pub struct WikiCycles {
    pub sets: BTreeMap<String, Vec<WikiCycle>>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct WikiCycle {
    pub id: String,
    /// In English; the other languages in `config/cycles.<lang>.json`, by this name.
    pub name: String,
    pub slots: Vec<Vec<String>>,
}

/// Our own cycles (`config/cycles.custom.json`).
#[derive(Debug, Clone, Deserialize)]
pub struct CustomCycles {
    #[serde(default)]
    pub sets: BTreeMap<String, Vec<CustomCycle>>,
    /// Wiki cycles not to show, as "SET/id".
    #[serde(default)]
    pub hidden: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CustomCycle {
    pub id: String,
    /// By language; English at least.
    pub name: BTreeMap<String, String>,
    pub slots: Vec<Vec<String>>,
}

/// The names of the wiki's cycles in another language, by their English name.
pub type CycleTranslations = BTreeMap<String, String>;

/// A cycle, wherever it comes from.
#[derive(Debug, Clone, PartialEq)]
pub struct Cycle {
    pub id: String,
    /// By language, English always there.
    pub names: BTreeMap<String, String>,
    /// One of ours, not the wiki's.
    pub custom: bool,
    pub slots: Vec<Vec<String>>,
}

impl Cycle {
    /// Its name in `lang`, else in English.
    pub fn name(&self, lang: &str) -> &str {
        self.names.get(lang).or_else(|| self.names.get("en")).map_or(self.id.as_str(), String::as_str)
    }
}

/// Every cycle, by set code.
#[derive(Debug, Clone, Default)]
pub struct Cycles {
    by_set: HashMap<String, Vec<Cycle>>,
}

impl Cycles {
    /// Puts the wiki's cycles (their names translated) and ours together: one of ours
    /// replaces the wiki's of the same id, the hidden ones go.
    pub fn build(
        wiki: WikiCycles,
        custom: CustomCycles,
        translations: &BTreeMap<String, CycleTranslations>,
    ) -> Result<Self, ConfigError> {
        let bad = |msg: String| Err(ConfigError::Invalid(format!("cycles: {msg}")));
        let hidden: HashSet<&str> = custom.hidden.iter().map(String::as_str).collect();
        let mut by_set: HashMap<String, Vec<Cycle>> = HashMap::new();
        for (code, cycles) in wiki.sets {
            let list = by_set.entry(code.clone()).or_default();
            for c in cycles {
                if hidden.contains(format!("{code}/{}", c.id).as_str()) {
                    continue;
                }
                let mut names = BTreeMap::from([("en".to_string(), c.name.clone())]);
                for (lang, texts) in translations {
                    if let Some(text) = texts.get(&c.name) {
                        names.insert(lang.clone(), text.clone());
                    }
                }
                list.push(Cycle { id: c.id, names, custom: false, slots: c.slots });
            }
        }
        for (code, cycles) in custom.sets {
            let list = by_set.entry(code.clone()).or_default();
            for c in cycles {
                if !c.name.contains_key("en") {
                    return bad(format!("{code}/{} has no English name", c.id));
                }
                let cycle = Cycle { id: c.id, names: c.name, custom: true, slots: c.slots };
                match list.iter_mut().find(|w| w.id == cycle.id) {
                    Some(wiki) => *wiki = cycle,
                    None => list.push(cycle),
                }
            }
        }
        for (code, list) in &by_set {
            let mut ids = HashSet::new();
            for c in list {
                if c.id.is_empty() || !ids.insert(c.id.as_str()) {
                    return bad(format!("{code}: id `{}` empty or twice", c.id));
                }
                if c.slots.len() < 2 || c.slots.iter().any(Vec::is_empty) {
                    return bad(format!("{code}/{}: at least two slots, each with a printing", c.id));
                }
            }
        }
        by_set.retain(|_, list| !list.is_empty());
        Ok(Self { by_set })
    }

    /// Reads the files' texts: the wiki's, ours, and the translations by language.
    pub fn from_json(wiki: &str, custom: &str, translations: &[(&str, &str)]) -> Result<Self, ConfigError> {
        let parse = |what: &str, e: serde_json::Error| ConfigError::Invalid(format!("cycles ({what}): {e}"));
        let wiki: WikiCycles = serde_json::from_str(wiki).map_err(|e| parse("wiki", e))?;
        let custom: CustomCycles = serde_json::from_str(custom).map_err(|e| parse("custom", e))?;
        let mut texts = BTreeMap::new();
        for (lang, text) in translations {
            texts.insert(lang.to_string(), serde_json::from_str(text).map_err(|e| parse(lang, e))?);
        }
        Self::build(wiki, custom, &texts)
    }

    /// The cycles of a set, in their order (the wiki's, then ours).
    pub fn of_set(&self, code: &str) -> &[Cycle] {
        self.by_set.get(code).map_or(&[], Vec::as_slice)
    }

    /// The codes of the sets that have cycles.
    pub fn set_codes(&self) -> impl Iterator<Item = &str> {
        self.by_set.keys().map(String::as_str)
    }
}
